begin;create extension if not exists pgtap with schema extensions;select plan(32);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values
('00000000-0000-0000-0000-000000000000','17000000-0000-0000-0000-000000000001','authenticated','authenticated','lie-host@test.local','',now(),'{}','{}',now(),now()),
('00000000-0000-0000-0000-000000000000','17000000-0000-0000-0000-000000000002','authenticated','authenticated','lie-other@test.local','',now(),'{}','{}',now(),now()),
('00000000-0000-0000-0000-000000000000','27000000-0000-0000-0000-000000000001','authenticated','authenticated',null,'',now(),'{"provider":"anonymous","providers":["anonymous"]}','{}',now(),now()),
('00000000-0000-0000-0000-000000000000','27000000-0000-0000-0000-000000000002','authenticated','authenticated',null,'',now(),'{"provider":"anonymous","providers":["anonymous"]}','{}',now(),now());
insert into public.profiles(id)values('17000000-0000-0000-0000-000000000001'),('17000000-0000-0000-0000-000000000002');
insert into public.events(id,host_id,room_code,name,event_date,status,display_mode)values('a7000000-0000-0000-0000-000000000001','17000000-0000-0000-0000-000000000001','LIE123','Perfect Lie Night','2026-08-20','lobby','game');
insert into public.teams(id,event_id,auth_user_id,name,mascot_id)values
('d7000000-0000-0000-0000-000000000001','a7000000-0000-0000-0000-000000000001','27000000-0000-0000-0000-000000000001','Frogs','frog'),
('d7000000-0000-0000-0000-000000000002','a7000000-0000-0000-0000-000000000001','27000000-0000-0000-0000-000000000002','Robots','robot');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"17000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":false}',true);
select lives_ok($$select public.save_perfect_lie_round('a7000000-0000-0000-0000-000000000001','Perfect Lie','[{"title":"This Week","questions":[{"question_text":"The record gathering dressed as what?","correct_answer":"Bees","accepted_answer_variants":["A bee"],"explanation":"A swarm of record breakers.","source_reference":"Host source"},{"question_text":"Second question?","correct_answer":"Two"}]},{"title":"Sport","questions":[{"question_text":"Sport question?","correct_answer":"Goal"}]}]')$$,'Host creates Perfect Lie round');
reset role;select is((select count(*)from public.perfect_lie_categories),2::bigint,'arbitrary category count persists');select is((select count(*)from public.perfect_lie_questions),3::bigint,'arbitrary question count persists');select is((select string_agg(title,','order by position)from public.perfect_lie_categories),'This Week,Sport','category ordering persists');select is((select string_agg(question_text,','order by position)from public.perfect_lie_questions where category_id=(select id from public.perfect_lie_categories where position=1)),'The record gathering dressed as what?,Second question?','question ordering persists');
select set_config('test.q',(select id::text from public.perfect_lie_questions where question_text='The record gathering dressed as what?'),true);
set local role authenticated;select set_config('request.jwt.claims','{"sub":"17000000-0000-0000-0000-000000000002","role":"authenticated","is_anonymous":false}',true);select throws_ok($$select public.save_perfect_lie_round('a7000000-0000-0000-0000-000000000001','Attack','[]')$$,'42501','event owner required','non-owner cannot edit');
select set_config('request.jwt.claims','{"sub":"27000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":true}',true);select throws_ok($$select * from public.perfect_lie_question_secrets$$,'42501','permission denied for table perfect_lie_question_secrets','Team cannot read secrets directly');select throws_ok($$select public.start_perfect_lie_question('a7000000-0000-0000-0000-000000000001',current_setting('test.q')::uuid,20)$$,'42501','event owner required','Team cannot start question');
select set_config('request.jwt.claims','{"sub":"17000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":false}',true);select lives_ok($$select public.start_perfect_lie_question('a7000000-0000-0000-0000-000000000001',current_setting('test.q')::uuid,20)$$,'Host starts question');
select set_config('request.jwt.claims','{"sub":"27000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":true}',true);select is((public.submit_perfect_lie_answer('d7000000-0000-0000-0000-000000000001',current_setting('test.q')::uuid,'  A BEE!  ')->>'knew_truth')::boolean,true,'accepted normalized variant recognized');select lives_ok($$select public.submit_perfect_lie_lie('d7000000-0000-0000-0000-000000000001',current_setting('test.q')::uuid,'Elvis Presley')$$,'truth-knower still submits a lie');
select set_config('request.jwt.claims','{"sub":"27000000-0000-0000-0000-000000000002","role":"authenticated","is_anonymous":true}',true);select is((public.submit_perfect_lie_answer('d7000000-0000-0000-0000-000000000002',current_setting('test.q')::uuid,'Pirates')->>'knew_truth')::boolean,false,'wrong answer is recorded without revealing truth');select throws_ok($$select public.submit_perfect_lie_lie('d7000000-0000-0000-0000-000000000002',current_setting('test.q')::uuid,'bees.')$$,'22023','That’s the real answer — you need a lie.','truth-as-lie rejected');select throws_ok($$select public.submit_perfect_lie_lie('d7000000-0000-0000-0000-000000000002',current_setting('test.q')::uuid,' ELVIS   PRESLEY ')$$,'23505','Someone else beat you to that one. Try another lie.','normalized duplicate lie rejected');select lives_ok($$select public.submit_perfect_lie_lie('d7000000-0000-0000-0000-000000000002',current_setting('test.q')::uuid,'Dinosaurs')$$,'second unique lie accepted');select throws_ok($$select public.submit_perfect_lie_lie('d7000000-0000-0000-0000-000000000002',current_setting('test.q')::uuid,'Mario')$$,'23505','Someone else beat you to that one. Try another lie.','one final lie per Team');
select set_config('request.jwt.claims','{"sub":"17000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":false}',true);select lives_ok($$select public.close_perfect_lie_writing('a7000000-0000-0000-0000-000000000001')$$,'Host opens voting');reset role;
select is((select count(*)from public.perfect_lie_vote_options),3::bigint,'pool contains truth plus every accepted lie');select is((select count(*)from public.perfect_lie_vote_options where is_truth),1::bigint,'pool contains exactly one truth');select is((select count(distinct display_position)from public.perfect_lie_vote_options),3::bigint,'voting order is persisted');select set_config('test.truth',(select id::text from public.perfect_lie_vote_options where is_truth),true);select set_config('test.lie1',(select o.id::text from public.perfect_lie_vote_options o join public.perfect_lie_lies l on l.id=o.lie_id where l.team_id='d7000000-0000-0000-0000-000000000001'),true);
set local role authenticated;select set_config('request.jwt.claims','{"sub":"27000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":true}',true);select throws_ok($$select public.submit_perfect_lie_vote('d7000000-0000-0000-0000-000000000001',current_setting('test.q')::uuid,current_setting('test.lie1')::uuid)$$,'42501','You cannot vote for your own lie.','own-lie vote rejected');select lives_ok($$select public.submit_perfect_lie_vote('d7000000-0000-0000-0000-000000000001',current_setting('test.q')::uuid,current_setting('test.truth')::uuid)$$,'truth-knower may vote without duplicate truth points');
select set_config('request.jwt.claims','{"sub":"27000000-0000-0000-0000-000000000002","role":"authenticated","is_anonymous":true}',true);select lives_ok($$select public.submit_perfect_lie_vote('d7000000-0000-0000-0000-000000000002',current_setting('test.q')::uuid,current_setting('test.lie1')::uuid)$$,'another Team votes for lie');select throws_ok($$select public.submit_perfect_lie_vote('d7000000-0000-0000-0000-000000000002',current_setting('test.q')::uuid,current_setting('test.truth')::uuid)$$,'23505','duplicate key value violates unique constraint "perfect_lie_votes_question_id_team_id_key"','one vote per Team');
select set_config('request.jwt.claims','{"sub":"17000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":false}',true);select lives_ok($$select public.start_perfect_lie_reveal('a7000000-0000-0000-0000-000000000001')$$,'Host scores and starts staged reveal');select lives_ok($$select public.start_perfect_lie_reveal('a7000000-0000-0000-0000-000000000001')$$,'scoring retry is idempotent');reset role;
select is((select sum(points)from public.score_awards where team_id='d7000000-0000-0000-0000-000000000001'and metadata->>'game_type'='perfect_lie'),5::bigint,'truth max +3 plus +2 per fooled Team');select is((select count(*)from public.score_awards where team_id='d7000000-0000-0000-0000-000000000001'and metadata->>'award_type'='truth'),1::bigint,'initial truth and vote do not double-award');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"27000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":true}',true);select ok((public.get_public_room_state('LIE123')->'perfect_lie'->'question'->>'correct_answer')is not null,'Audience receives truth only after reveal');select ok((public.get_team_room_state('LIE123')->'perfect_lie'->'my_response'->>'knew_truth')::boolean,'Team hydration preserves knowledge state');select set_config('request.jwt.claims','{"sub":"17000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":false}',true);select lives_ok($$select public.advance_perfect_lie_reveal('a7000000-0000-0000-0000-000000000001')$$,'Host manually advances reveal');select set_config('request.jwt.claims','{"sub":"27000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":true}',true);select throws_ok($$select public.advance_perfect_lie_reveal('a7000000-0000-0000-0000-000000000001')$$,'42501','event owner required','Team cannot control reveal');
select * from finish();rollback;
